package com.bendemenstudios.steampunksync.client;
import com.bendemenstudios.steampunksync.config.SteampunkSyncConfig;import com.bendemenstudios.steampunksync.model.VersionManifest;import com.bendemenstudios.steampunksync.util.VersionComparator;import com.google.gson.Gson;import net.minecraft.client.Minecraft;import net.neoforged.neoforge.client.event.ClientTickEvent;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.bus.api.SubscribeEvent;import java.net.URI;import java.net.http.*;import java.time.Duration;
public final class UpdateCoordinator{private static final Gson GSON=new Gson();private static final HttpClient HTTP=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();private static boolean started,screenOpened;private UpdateCoordinator(){}public static void register(){NeoForge.EVENT_BUS.register(UpdateCoordinator.class);}
@SubscribeEvent public static void onClientTick(ClientTickEvent.Post e){if(started||!SteampunkSyncConfig.ENABLE_AUTO_UPDATE.get())return;started=true;Minecraft mc=Minecraft.getInstance();ClientUpdateState.load(mc.gameDirectory.toPath());Thread.startVirtualThread(UpdateCoordinator::checkNow);}
private static void checkNow(){try{String body=HTTP.send(HttpRequest.newBuilder(URI.create(SteampunkSyncConfig.VERSION_URL.get())).timeout(Duration.ofSeconds(15)).header("Accept","application/json").GET().build(),HttpResponse.BodyHandlers.ofString()).body();VersionManifest m=GSON.fromJson(body,VersionManifest.class);if(m==null||m.version()==null||m.download()==null||m.sha256()==null)return;String installed=ClientUpdateState.installedVersion();if(installed!=null&&VersionComparator.compare(m.version(),installed)<=0)return;ClientUpdateState.setAvailable(m);Minecraft.getInstance().execute(()->{if(!screenOpened){screenOpened=true;Minecraft.getInstance().setScreen(new SteampunkSyncScreen(m));}});}catch(Exception ignored){}}}
